  add5("verbal", "The committee decided ------- the annual conference to a larger venue.", ["to move", "moving", "moved", "move"], 0, "decide 後面接不定詞：decide to V。decide moving 是錯的。", "委員會決定把年度會議移到更大的場地。", ["移動（不定詞）", "移動（動名詞）", "移動（過去式）", "移動（原形）"], [["committee", "委員會"], ["venue", "場地"]]);
