  add5("verbal", "The manager reminded the staff ------- their timesheets by Friday.", ["to submit", "submitting", "submit", "submitted"], 0, "remind 人 to V＝提醒某人去做某事。", "經理提醒員工週五前交工時表。", ["交（不定詞）", "交（動名詞）", "交（原形）", "交（過去式）"], [["timesheet", "工時表"]]);
  add5("verbal", "------- the report carefully, Ms. Tran noticed several errors in the sales figures.", ["Reading", "Read", "To be read", "Reads"], 0, "分詞構句：主詞 Ms. Tran 主動「閱讀」，用現在分詞 Reading。", "Tran 女士仔細看報告時，發現銷售數字有幾個錯誤。", ["閱讀（現在分詞）", "閱讀（原形／過去分詞）", "將被閱讀", "閱讀（第三人稱單數）"], [["sales figures", "銷售數字"]]);
  add5("verbal", "The results of the survey were ------- to everyone in the marketing department.", ["surprising", "surprised", "surprise", "surprisingly"], 0, "結果「令人驚訝」，事物當主詞用 -ing 形容詞 surprising。人感到驚訝才用 surprised。", "問卷調查的結果讓行銷部的每個人都很驚訝。", ["令人驚訝的", "感到驚訝的", "驚訝（名詞／動詞）", "驚人地"], [["survey", "問卷調查"]]);
  add5("verbal", "Please avoid ------- personal calls during business hours.", ["making", "to make", "make", "made"], 0, "avoid 後面接動名詞：avoid V-ing。", "上班時間請避免打私人電話。", ["打（動名詞）", "打（不定詞）", "打（原形）", "打（過去式）"], [["business hours", "營業／上班時間"]]);
  add5("verbal", "The new software allows employees ------- their schedules from any device.", ["to manage", "managing", "manage", "managed"], 0, "allow 人 to V＝讓某人能夠做某事。", "新軟體讓員工能用任何裝置管理自己的行程。", ["管理（不定詞）", "管理（動名詞）", "管理（原形）", "管理（過去式）"], [["device", "裝置"]]);
  add5("verbal", "Having ------- the contract, the two companies issued a joint press release.", ["signed", "signing", "sign", "to sign"], 0, "Having + 過去分詞＝完成式分詞構句，表示「簽完約之後」。", "兩家公司簽約後，發布了聯合新聞稿。", ["簽（過去分詞）", "簽（現在分詞）", "簽（原形）", "簽（不定詞）"], [["joint", "共同的"], ["press release", "新聞稿"]]);
  add5("verbal", "The museum is closed this week ------- the installation of a new exhibit.", ["to allow for", "allowing to", "allowed for", "allow"], 0, "to allow for＝為了容許、為了讓……進行，不定詞表目的。", "博物館本週閉館，以便布置新的展覽。", ["為了容許（不定詞）", "（錯誤搭配）", "已容許", "容許（原形）"], [["installation", "布置；安裝"], ["exhibit", "展覽"]]);

