  add5("pos", "Sales of the new model have increased ------- since the price was reduced.", ["steadily", "steady", "steadiness", "steadied"], 0, "修飾動詞 increased 要用副詞 steadily。", "自從降價後，新機型的銷量穩定成長。", ["穩定地 (adv.)", "穩定的 (adj.)", "穩定性 (n.)", "使穩定（過去式）"], []);
  add5("pos", "All visitors must show valid ------- at the security desk.", ["identification", "identify", "identifiable", "identified"], 0, "形容詞 valid 後面要接名詞 identification（身分證明）。", "所有訪客都必須在保全櫃檯出示有效的身分證明。", ["身分證明 (n.)", "辨認 (v.)", "可辨認的 (adj.)", "被辨認的 (p.p.)"], [["valid", "有效的"], ["security desk", "保全櫃檯"]]);
  add5("pos", "The design team worked ------- to meet the client's deadline.", ["tirelessly", "tireless", "tire", "tiredness"], 0, "修飾動詞 worked 用副詞 tirelessly（不辭辛勞地）。", "設計團隊不辭辛勞地趕上客戶的截止期限。", ["不辭辛勞地 (adv.)", "不知疲倦的 (adj.)", "使疲倦 (v.)", "疲倦 (n.)"], [["meet a deadline", "趕上截止期限"]]);
  add5("pos", "Ms. Bauer is known for her ------- to detail.", ["attention", "attentive", "attend", "attentively"], 0, "所有格 her 後接名詞；attention to detail＝注重細節，固定說法。", "Bauer 女士以注重細節聞名。", ["注意 (n.)", "專注的 (adj.)", "參加 (v.)", "專注地 (adv.)"], [["be known for", "以……聞名"]]);
  add5("pos", "The hotel offers ------- rates for guests who stay more than five nights.", ["discounted", "discount", "discounting", "discounter"], 0, "修飾名詞 rates 用形容詞化的過去分詞 discounted（打折的）。", "飯店為住五晚以上的房客提供折扣價。", ["打折的", "折扣 (n.)", "打折中", "折扣商"], [["rate", "價格；費率"]]);
  add5("pos", "The company's growth has been largely ------- to its strong online presence.", ["attributable", "attribute", "attribution", "attributing"], 0, "be 動詞 has been 後接形容詞；be attributable to＝可歸因於。", "公司的成長大致可歸功於它強大的網路聲量。", ["可歸因於的 (adj.)", "歸因於 (v.)", "歸因 (n.)", "歸因中"], [["online presence", "網路能見度"]]);
  add5("pos", "Mr. Lindqvist spoke ------- about the need for better training programs.", ["persuasively", "persuasive", "persuade", "persuasion"], 0, "修飾動詞 spoke 用副詞 persuasively。", "Lindqvist 先生很有說服力地談到需要更好的訓練課程。", ["有說服力地 (adv.)", "有說服力的 (adj.)", "說服 (v.)", "說服 (n.)"], []);

  /* ---------- Part 5：時態、語態、一致 ---------- */
  add5("tense", "By the time the new CEO arrives next month, the restructuring ------- .", ["will have been completed", "has been completed", "was completed", "is completing"], 0, "By the time + 未來事件，表示在那之前已完成，用未來完成式；重組是「被完成」，所以用被動。", "新執行長下個月到任前，重組會已經完成。", ["將已被完成", "已被完成", "曾被完成", "正在完成"], [["restructuring", "重組"]]);
  add5("tense", "Ms. Patel ------- in the accounting department since she joined the firm in 2019.", ["has worked", "works", "worked", "is working"], 0, "since + 過去時間點，表示從那時到現在，用現在完成式 has worked。", "Patel 女士自 2019 年進公司以來一直在會計部工作。", ["一直工作（現在完成式）", "工作（現在式）", "工作（過去式）", "正在工作"], [["accounting department", "會計部"]]);
  add5("tense", "If the shipment ------- on time, we will be able to open the store on Saturday.", ["arrives", "will arrive", "arrived", "would arrive"], 0, "if 條件句表未來時，if 子句用現在式代替未來式。", "如果貨準時到，我們週六就能開店。", ["到達（現在式）", "將到達", "到達（過去式）", "會到達（假設）"], [["shipment", "貨物"]]);
  add5("tense", "The board ------- the proposal when the fire alarm went off.", ["was discussing", "discussed", "has discussed", "discusses"], 0, "過去某動作進行中時被另一件事打斷，用過去進行式 was discussing。", "火災警報響起時，董事會正在討論這項提案。", ["正在討論（過去進行式）", "討論了（過去式）", "已經討論", "討論（現在式）"], [["go off", "（警報）響起"]]);
  add5("voice", "Applications ------- after the deadline will not be considered.", ["received", "receiving", "receive", "are received"], 0, "主要動詞是 will not be considered，空格修飾 Applications；申請書是「被收到」的，用過去分詞 received。", "截止日後收到的申請書將不予受理。", ["被收到的（過去分詞）", "收到中", "收到（原形）", "被收到（完整動詞）"], [["consider", "考慮；受理"]]);
  add5("voice", "The new branch office ------- by the regional director next Tuesday.", ["will be opened", "will open", "opens", "has opened"], 0, "分店是「被」區域主管開幕，用被動；next Tuesday 是未來，用 will be opened。", "新分行下週二將由區域主管主持開幕。", ["將被開幕（被動）", "將開幕（主動）", "開幕（現在式）", "已開幕"], [["branch office", "分行；分公司"], ["regional director", "區域主管"]]);
