  add5("agree", "Neither the manager nor the assistants ------- aware of the change in schedule.", ["were", "was", "is", "has been"], 0, "neither A nor B 的動詞跟最靠近的 B 一致；the assistants 是複數，用 were。", "經理和助理們都不知道行程有變。", ["是（複數過去式）", "是（單數過去式）", "是（單數現在式）", "已經是（單數）"], [["be aware of", "知道"]]);
  add5("agree", "Each of the proposals ------- a detailed cost estimate.", ["includes", "include", "including", "are including"], 0, "Each of + 複數名詞，主詞是 Each，動詞用單數 includes。", "每一份提案都附有詳細的成本估算。", ["包含（單數）", "包含（複數）", "包含中", "正在包含（複數）"], [["cost estimate", "成本估算"]]);
