  ZH6.push({ t: "從週一開始，我們的新鮮蔬果將改由 Greenfield 農場配送，不再用目前的供應商。每天早上 6 點 30 分送達。簽收前請仔細核對每筆訂單和發票。任何破損或缺少的品項，請立刻向我回報。Greenfield 農場已同意當天補送。我相信這項改變會提升我們菜色的品質。",
    w: [["produce", "蔬果農產品"], ["invoice", "發票；請款單"], ["sign for", "簽收"], ["replace", "更換；補送"]],
    q: [[["在（時間點）", "在（日期）", "在（期間）", "在……之前"]], [["在……之前", "（需加 to）", "直到", "自從"]],
      [["Greenfield 農場已同意當天補送。", "餐廳下個月將閉店整修。", "我們的甜點菜單特別受觀光客歡迎。", "到班時請記得打卡。"], ["✓ 前句講破損缺貨要回報，這句說供應商會當天補送，正好接上。", "✗ 整修和換供應商無關。", "✗ 甜點受歡迎和進貨流程無關。", "✗ 打卡和收貨流程無關。"]],
      [["品質 (n.)", "使有資格 (v.)", "有資格的 (adj.)", "質性的 (adj.)"]]] });

  P6.push({ title: "Article", head: "Local Bakery Expands",
    text: "Rise & Shine Bakery, a family-owned business on Main Street, will open a second location in the Eastgate Shopping Center this fall. Owner Teresa Kim started the bakery ten years ago with [1] three employees. Today, it employs more than thirty people. \"Our customers have been asking us to open closer to the east side for years,\" Ms. Kim said. [2] The new shop will be twice as large as the original, with seating for [3] forty customers. Ms. Kim plans [4] at least fifteen new staff members before the opening.",
    qs: [
      ["vocab", ["only", "alone", "single", "lonely"], 0, "with only three employees＝只有三名員工；only 修飾數量。"],
      ["context", ["Eastgate is home to several large office buildings, which should bring in many morning customers.", "The bakery's bread is made with organic flour.", "Main Street will be closed for a parade next week.", "Ms. Kim studied business at a local college."], 0, "前句說顧客希望在東區開店，這句接著說明 Eastgate 的地點優勢，論點最連貫。"],
      ["vocab", ["up to", "as of", "such as", "in spite of"], 0, "seating for up to forty customers＝最多可坐四十人。"],
      ["verbal", ["to hire", "hiring", "hire", "hired"], 0, "plan to V＝計畫做某事。"]
    ] });
  ZH6.push({ t: "Main 街上的家族經營麵包店 Rise & Shine，今年秋天將在 Eastgate 購物中心開設第二家店。老闆 Teresa Kim 十年前創業時只有三名員工，現在已經雇用超過三十人。「我們的顧客好幾年來一直要我們在靠近東區的地方開店，」Kim 女士說。Eastgate 有好幾棟大型辦公大樓，應該能帶來很多早上的客人。新店面積是原店的兩倍，最多可容納四十位客人。Kim 女士計畫在開幕前至少再招募十五名員工。",
    w: [["family-owned", "家族經營的"], ["location", "分店；地點"], ["employ", "雇用"], ["seating", "座位"]],
    q: [[["只有", "單獨", "單一的", "孤單的"]],
      [["Eastgate 有好幾棟大型辦公大樓，應該能帶來很多早上的客人。", "這家店的麵包使用有機麵粉。", "Main 街下週因遊行封路。", "Kim 女士在當地大學念商科。"], ["✓ 前句說顧客希望在東區開店，這句補充 Eastgate 的地點優勢，最連貫。", "✗ 麵粉和開分店無關。", "✗ 遊行封路和展店無關。", "✗ 老闆的學歷放在這裡打斷了開店的話題。"]],
      [["最多", "截至", "例如", "儘管"]], [["招募（不定詞）", "招募（動名詞）", "招募（原形）", "招募（過去式）"]]] });

  P6.push({ title: "E-mail", head: "To: Paolo Ricci\nFrom: Nadia Ivanova\nSubject: Quarterly sales meeting",
    text: "Hi Paolo,\n\nI am writing to confirm the arrangements for next week's quarterly sales meeting. As we discussed, the meeting will take place in the main conference room on Thursday afternoon. I have already sent the agenda to all regional managers. [1], I still need the updated sales figures from your team. Could you send them to me [2] Tuesday? That way, I will have enough time to include them in the presentation. [3] Thank you for your help, and please let me know if you have any [4].\n\nNadia",
    qs: [
      ["conj", ["However", "Therefore", "Similarly", "For example"], 0, "前句說議程已寄出（已完成），後句說還缺資料（未完成），語意轉折用 However。"],
      ["prep", ["by", "until", "within", "since"], 0, "by Tuesday＝最晚週二前（截止期限）。until 表示動作持續到某時。"],
      ["context", ["I would also appreciate it if you could prepare a brief summary of your team's results.", "The conference room was painted last month.", "Our company was founded more than twenty years ago.", "I will be on vacation for the next two weeks."], 0, "前面在請 Paolo 準備資料，這句再補充請他準備成果摘要，最連貫。"],
      ["pos", ["concerns", "concerned", "concerning", "concernedly"], 0, "any 後面接名詞；if you have any concerns＝如果你有任何疑慮。"]
    ] });
  ZH6.push({ t: "Paolo 你好：\n\n我寫信確認下週季度業務會議的安排。如我們討論過的，會議週四下午在主會議室舉行。我已經把議程寄給各區經理了。不過，我還需要你們團隊最新的銷售數字。可以請你在週二前寄給我嗎？這樣我才有足夠時間放進簡報。如果你能準備一份團隊成果的簡短摘要，我也會很感謝。謝謝你的幫忙，有任何疑慮請告訴我。\n\nNadia",
    w: [["arrangement", "安排"], ["agenda", "議程"], ["regional manager", "區經理"], ["summary", "摘要"]],
    q: [[["不過", "因此", "同樣地", "例如"]], [["最晚在……之前", "直到", "在……之內", "自從"]],
      [["如果你能準備一份團隊成果的簡短摘要，我也會很感謝。", "會議室上個月重新粉刷過。", "我們公司成立超過二十年了。", "我接下來兩週要休假。"], ["✓ 前面請他寄資料，這句再請他準備摘要，同一件事延伸，最自然。", "✗ 粉刷和會議準備無關。", "✗ 公司歷史和這封工作信無關。", "✗ 如果她要休假兩週，就和她週四要開會矛盾。"]],
      [["疑慮 (n.)", "擔心的 (adj.)", "關於 (prep.)", "擔心地 (adv.)"]]] });

